typedef struct {
    uint32_t format_version;
    uint16_t chunk_count;
    uint8_t  layout_mode;
    uint8_t  flags;
    uint64_t data_offset;
    uint64_t extra_offset;
    uint64_t meta_offset;
    uint32_t meta_size;
} HonzoHead;

TocEntry struct
typedef struct {
    uint8_t  chunk_type[4];
    uint8_t  content_type;
    uint8_t  compression;
    uint8_t  markup_type;
    uint8_t  cover_type;
    uint16_t language;
    uint16_t font_embedding;
    uint16_t font_license_url_len;
    uint64_t offset;
    uint32_t size;
    uint32_t orig_size;
} TocEntry;

Error handling
Functions return 0 on success and nonzero on error. Get the error message:
const char* msg = HonzoHandle_error(handle);
if (msg) {
    fprintf(stderr, &quot;Honzo error: %s\n&quot;, msg);
}

